// FICTIONAL TEST FIXTURE - not seed data, not demo data, not an operational record.
//
// Builds a small, internally consistent inventory ledger for demonstrating a
// "reconciled" result. It is generated by driving the REAL handlers (item
// registration with opening balance, supplier receipt, worksheet use, return,
// scrap, correction), so every quantity_before/after, unit and reference is
// produced by the shared ledger, never hand-written or back-filled.
//
// It lives under tests/ on purpose: the application seed (scripts/seed-realistic.js,
// src/curatedDemoData.js) is untouched, and pre-ledger records there are reported
// by reconciliation as incomplete rather than repaired.
import { createStockItem, recordStockMovement } from "../../src/controllers/inventoryController.js";
import { addMaterialUsage } from "../../src/controllers/dispatchController.js";

const res = () => ({ statusCode: 200, status(c) { this.statusCode = c; return this; }, json(b) { this.body = b; return this; } });

export function buildValidLedgerFixture() {
  let n = 0;
  const users = [
    { id: "fx-u-ops", role: "Operations", name: "Fixture Operations", is_active: true },
    { id: "fx-u-tech", role: "Technician", name: "Fixture Technician", is_active: true }
  ];
  const db = {
    users, clients: [], quotes: [],
    suppliers: [{ id: "fx-sup", name: "Fixture Supplies (fictional)" }],
    dispatch_cards: [{ id: "fx-dc", dispatch_number: "FX-JOB-0001", assigned_technician_id: "fx-u-tech" }],
    material_usage: [], stock_items: [], stock_movements: []
  };
  const store = { id: (p) => `fx-${p}-${++n}`, audit: () => {}, recalculateVariance: () => {} };
  const ctx = (userId, extra) => ({ user: { id: userId }, db, store, params: {}, query: {}, headers: {}, ...extra });
  const ok = (r, label) => { if (r.statusCode !== 200) throw new Error(`fixture step failed (${label}): ${r.statusCode} ${r.body?.message}`); return r; };

  ok((() => { const r = res(); createStockItem(ctx("fx-u-ops", { body: { catalog_item_id: "fx-cat", item_code: "FX-VALID-A", item_name: "Fixture Gasket (fictional)", unit_of_measure: "each", quantity_on_hand: 20, reorder_level: 5 } }), r); return r; })(), "register");
  const move = (body, label) => ok((() => { const r = res(); recordStockMovement(ctx("fx-u-ops", { body }), r); return r; })(), label);
  const itemId = db.stock_items[0].id;

  move({ stock_item_id: itemId, movement_type: "in", quantity: 10, reason: "Delivery (fictional)", reference_type: "supplier", reference_id: "fx-sup", source_document_ref: "FX-DN-0001" }, "receipt");
  ok((() => { const r = res(); addMaterialUsage(ctx("fx-u-tech", { params: { id: "fx-dc" }, body: { catalog_item_id: "fx-cat", description: "Fixture Gasket", quantity_used: 4, unit_cost: 1, idempotency_key: "fixture-use-0001" } }), r); return r; })(), "use");
  move({ stock_item_id: itemId, movement_type: "in", quantity: 1, reason: "Unused, returned", reference_type: "return", reference_id: "fx-dc" }, "return");
  move({ stock_item_id: itemId, movement_type: "out", quantity: 2, reason: "Damaged", reference_type: "scrap" }, "scrap");
  move({ stock_item_id: itemId, movement_type: "adjustment", quantity: -1, reason: "Count correction (fictional)" }, "correction");

  // 20 opening + 10 receipt - 4 used + 1 returned - 2 scrapped - 1 corrected
  return { db, store, expected: { "FX-VALID-A": { quantity_on_hand: 24, movements: 6 } } };
}
